import 'package:flutter/material.dart';import 'package:introduction_screen/introduction_screen.dart';import '../../../../Core/Resources/app_constants.dart';import '../../../../Core/Resources/app_list.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Config/Routes/route_name.dart';import "../../../../main.dart";import '../widgets/build_button_boarding.dart';class BoardingScreen extends StatelessWidget {  const BoardingScreen({super.key});  @override  Widget build(BuildContext context) {    return Scaffold(      body: IntroductionScreen(        globalBackgroundColor: AppColors.backgroundColor,        pages: AppList.buildPagesIntroductionScreen(context),        showBackButton: true,        showSkipButton: false,        showNextButton: true,        next: buildButtonBoarding(context, context.local.Next),        back: buildButtonBoarding(context, context.local.Back),        dotsDecorator: AppConstants.dotsDecoration,        done: buildButtonBoarding(context, context.local.Continue),        showDoneButton: true,        onDone: () =>            kNavigationService.clearAndNavigateTo(AppRoutes.authentication),      ),    );  }}